import{_ as r,C as a,o as s,c as n,a2 as t,j as l,E as d}from"./chunks/framework.B_GyVC5q.js";const x=JSON.parse('{"title":"REST Export","description":"","frontmatter":{"title":"REST Export"},"headers":[],"relativePath":"guide/rest-export.md","filePath":"guide/rest-export.md"}'),i={name:"guide/rest-export.md"};function c(p,e,h,g,u,m){const o=a("DocScreenshot");return s(),n("div",null,[e[0]||(e[0]=t('<h1 id="rest-export" tabindex="-1">REST Export <a class="header-anchor" href="#rest-export" aria-label="Permalink to &quot;REST Export&quot;">​</a></h1><p>Build a <strong>Collection v2.1</strong> or <strong>OpenAPI 3.1</strong> toolkit from the connected 4D REST catalog. Open it from the <strong>Tools menu</strong> or the command palette (<strong>REST Export</strong>). <a href="/4d-dataexplorer/guide/parts.html#rest-export">Named parts</a>.</p>',2)),l("p",null,[d(o,{src:"/screenshots/39-rest-export.png",alt:"REST Export"})]),e[1]||(e[1]=t('<p>HTTP Client and Method Executor can also export the current request or favourites as a collection or OpenAPI — see <a href="/4d-dataexplorer/guide/http-client.html">HTTP Client</a> and <a href="/4d-dataexplorer/guide/method-executor.html">Method Executor</a>.</p><h2 id="wizard" tabindex="-1">Wizard <a class="header-anchor" href="#wizard" aria-label="Permalink to &quot;Wizard&quot;">​</a></h2><p>The tab is a four-step wizard. Use <strong>Next</strong> / <strong>Back</strong> (or the step indicator) to move between steps. Catalog and export preferences persist per profile.</p><table tabindex="0"><thead><tr><th>Step</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Selection</strong></td><td>Choose <strong>Expanded</strong> or <strong>Collection variable</strong> dataclass mode, then dataclasses and singletons. Refresh the catalog if the structure changed.</td></tr><tr><td><strong>Categories</strong></td><td>Toggle request groups (auth, catalog, CRUD, entity sets, functions, …). Core and advanced groups each have select / unselect all.</td></tr><tr><td><strong>Variables</strong></td><td>Collection name, description, base URL, and login variables (access key, username / password). Optionally include an access-key login request.</td></tr><tr><td><strong>Preview</strong></td><td>Review the folder tree, then export as Collection or OpenAPI.</td></tr></tbody></table><p><strong>Dataclass mode</strong> (Selection step, first choice):</p><ul><li><strong>Expanded</strong> (default) — one folder per selected dataclass with concrete paths (<code>/rest/Agency</code>) and <code>Functions/{dataclass|entity|entitySelection}</code>.</li><li><strong>Collection variable</strong> — one shared <code>DataClass</code> CRUD/catalog template using <code>{{Dataclass}}</code> (<code>/rest/$catalog/{{Dataclass}}</code>, <code>/rest/{{Dataclass}}</code>, …). The dataclass list only includes classes with member functions; those export as direct <code>dataclass</code> / <code>entity</code> / <code>entitySelection</code> subfolders (no <code>Functions</code> wrapper). The exported collection includes a <code>Dataclass</code> variable (defaults to the first selected dataclass). Use this for large catalogs so the export stays small.</li></ul><p><strong>Directory login</strong> and <strong>include non-exposed methods</strong> are off by default. Turn them on under <strong>Advanced</strong> on the Categories step if you need them.</p><h2 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h2><p>The preview tree starts <strong>collapsed</strong>. Expand or collapse a folder, or use the toolbar control to expand / collapse all (including a mixed state when only some folders are open).</p><h3 id="emojis" tabindex="-1">Emojis <a class="header-anchor" href="#emojis" aria-label="Permalink to &quot;Emojis&quot;">​</a></h3><ul><li>Toggle <strong>Emojis</strong> on or off for the whole export.</li><li><strong>Folder emoji on dataclasses</strong> is off by default.</li><li>Click an emoji (or the + control) on a request or folder to change or remove it. The picker includes a <strong>Professional</strong> tab for REST-oriented symbols.</li><li><strong>Shift-click</strong> an emoji or <strong>No emoji</strong> to apply or clear that choice for every item in the same category.</li></ul><h3 id="_4d-docs" tabindex="-1">4D docs <a class="header-anchor" href="#_4d-docs" aria-label="Permalink to &quot;4D docs&quot;">​</a></h3><p>When <strong>4D docs</strong> is on, each request links to the official <a href="https://developer.4d.com/docs/category/rest-api" target="_blank" rel="noreferrer">4D REST API</a> page. Collection request <strong>Docs</strong> include that page’s markdown; OpenAPI uses a short summary plus <code>externalDocs</code> and the known REST response statuses (200, 401, 402, 404, 500).</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Choose <strong>Collection</strong> or <strong>OpenAPI</strong> in the preview toolbar, then <strong>Export</strong>. Empty query parameters such as <code>$filter</code>, <code>$orderby</code>, and <code>$attributes</code> are <strong>disabled</strong> in the collection export by default so they are not sent until you fill them in.</p><h3 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h3><ul><li>Select only the dataclasses you need — the tree and file size stay smaller.</li><li>Use <strong>Collection variable</strong> dataclass mode for large 4D bases so CRUD is not duplicated per dataclass.</li><li>Uncheck categories you do not use (for example delete-all or compute / upload) before preview.</li><li>Collection name and variables are reused the next time you open REST Export.</li></ul>',17))])}const b=r(i,[["render",c]]);export{x as __pageData,b as default};
